INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Umum','Apa itu PT ASABRI (Persero)?','PT ASABRI (Persero) adalah BUMN yang ditugaskan menyelenggarakan Program Asuransi dan Pensiun bagi Prajurit TNI, Anggota Polri, dan pegawai ASN di lingkungan Kemhan dan Polri. Programnya: Tabungan Hari Tua (THT), Jaminan Kecelakaan Kerja (JKK), Jaminan Kematian (JKm), dan Pensiun, diatur PP 102 Tahun 2015 sebagaimana diubah PP 54 Tahun 2020.','profil asabri bumn apa itu program','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 1');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Kepesertaan','Siapa saja peserta ASABRI?','Sesuai Pasal 3 ayat (1) PP 102 Tahun 2015, peserta ASABRI adalah Prajurit TNI, Anggota Polri, dan Pegawai ASN di lingkungan Kementerian Pertahanan dan Polri.','peserta siapa tni polri asn pns','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 2');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Kepesertaan','Kapan kepesertaan ASABRI dimulai dan berakhir?','Kepesertaan bersifat wajib, dihitung mulai tanggal pengangkatan dan gaji dibayarkan sebagai Prajurit TNI, Anggota Polri, CPNS atau PPPK di lingkungan Kemhan dan Polri, dan berakhir apabila yang bersangkutan diberhentikan atau meninggal dunia.','masa kepesertaan mulai berakhir wajib','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 2–3');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Iuran','Berapa iuran peserta ASABRI?','Iuran peserta dari penghasilan (gaji pokok + tunjangan istri + tunjangan anak) setiap bulan: THT 3,25%, Pensiun 4,75%. Selain itu iuran BPJS Kesehatan 2%. Iuran JKK (0,62% gaji pokok) dan JKm (0,81% gaji pokok) dibayar pemerintah sebagai pemberi kerja.','iuran potongan gaji persen bayar','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 4, 12, 15, 28');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Kepesertaan','Apa hak peserta ASABRI?','Mendapatkan Nomor Kartu Peserta ASABRI (No. KPA); menerima manfaat THT, JKK, JKm dan Pensiun (dapat diberikan kepada keluarga/ahli waris sesuai aturan); memperoleh informasi hak dan kewajiban serta menyampaikan kritik dan saran kepada PT ASABRI.','hak peserta','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 5');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('KPA-e','Apa itu KPA-e?','Kartu Peserta ASABRI Elektronik (KPA-e) adalah kartu bukti kepesertaan virtual dengan QR Code sebagai tempat penyimpanan data peserta. KPA-e diunduh lewat aplikasi ASABRI Mobile dengan Nomor KPA-e dan nomor ponsel. ASABRI tidak lagi menerbitkan KPA fisik, dan KPA bukan alat jaminan pinjaman di bank.','kpa kpae kartu peserta elektronik qr','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 6–7');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('KPA-e','Apa syarat pengajuan KPA-e baru?','Surat pengantar dari Kesatuan/Lemdik; Keputusan Pengangkatan Pertama (hardcopy/softcopy PDF) dan Daftar Nominatif (softcopy Excel); fotokopi e-KTP; nomor ponsel.','syarat kpa baru daftar','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 11');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('KPA-e','KPA hilang atau rusak, bagaimana?','Unduh aplikasi ASABRI Mobile, login dengan Nomor KPA dan nomor ponsel (belum punya akun: klik Daftar, masukkan Nomor KPA dan NRP), lalu unduh KPA Elektronik. Lupa Nomor KPA: klik "Lupa Nomor KPA", input NIK, atau hubungi admin aplikasi dengan foto e-KTP dan nomor HP.','kpa kartu hilang rusak lupa nomor','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 11');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('THT','Apa itu Program Tabungan Hari Tua (THT)?','Tabungan dari iuran peserta dan pemerintah beserta pengembangannya, agar peserta menerima uang tunai saat berhenti, baik karena usia pensiun maupun bukan. Manfaatnya antara lain Tabungan Asuransi, Nilai Tunai Tabungan Asuransi, biaya pemakaman peserta pensiun Rp5.000.000, biaya pemakaman istri/suami Rp4.000.000, dan biaya pemakaman anak Rp3.000.000 (maks. 2 anak).','tht tabungan hari tua manfaat pemakaman','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 12–14');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('JKK','Apa itu Jaminan Kecelakaan Kerja (JKK)?','Perlindungan atas risiko kecelakaan atau penyakit akibat kerja selama masa dinas, termasuk kecelakaan dalam perjalanan rumah–tempat kerja. Manfaatnya berupa perawatan (rawat inap kelas I, operasi, rehabilitasi, angkutan, dll) dan santunan (cacat, gugur, tewas, beasiswa).','jkk kecelakaan kerja perawatan','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 15–16');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('JKK','Kecelakaan apa yang tidak dijamin JKK?','Antara lain: kecelakaan lalu lintas saat mengemudi tanpa SIM sesuai golongan atau tanpa standar keselamatan; general check up; bencana alam/dampak perang; saat melakukan tindak pidana; akibat perkelahian; menyakiti diri sendiri atau hobi berbahaya; kanker bukan akibat kerja; pengobatan alternatif; obat kosmetik.','tidak dijamin pengecualian jkk','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 18–19');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('JKK','Apa syarat Surat Jaminan Perawatan JKK?','Surat pengantar kesatuan; surat kronologi/berita acara kejadian dari POM TNI/Propam Polri/pejabat berwenang; Kartu Tanda Anggota; fotokopi e-KTP pengaju; surat keterangan rawat dan diagnosis dari rumah sakit. Kecelakaan di hari Minggu/libur atau di luar jam kerja harus berdasarkan Sprin atau Surat Tugas. Call center: 1500043, WA Perawatan 08111622133.','syarat surat jaminan perawatan sjp klaim','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 21–22');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('JKK','Berapa batas waktu klaim JKK?','Klaim perawatan JKK paling lambat 2 tahun sejak kecelakaan. Klaim perawatan penyakit akibat kerja paling lambat 5 tahun sejak keputusan pensiun. Klaim santunan cacat paling lambat 3 tahun sejak keputusan kecacatan.','batas waktu klaim kedaluwarsa jkk','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 23, 25');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('JKK','Berapa santunan risiko kematian khusus (gugur/tewas)?','SRKK Gugur Rp450.000.000 dan SRKK Tewas Rp350.000.000, diberikan kepada ahli waris setelah penetapan status oleh Menteri Pertahanan, Panglima TNI atau Kapolri. Ada juga Bantuan Beasiswa JKK Rp30.000.000 untuk 2 anak dari peserta gugur, tewas, atau cacat tingkat III.','santunan gugur tewas srkk beasiswa','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 26');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('JKm','Apa itu Jaminan Kematian (JKm) dan manfaatnya?','Perlindungan atas risiko kematian bukan akibat kecelakaan kerja/dinas khusus bagi peserta yang meninggal biasa dalam dinas aktif. Manfaat: Santunan Kematian Sekaligus (Perwira/PNS setara Rp30.000.000; Bintara/Tamtama/PNS setara Rp27.500.000), Uang Duka Wafat 3x gaji pokok terakhir, dan beasiswa Rp15.000.000 per anak (maks. 2 anak, ≤25 tahun, belum menikah, belum bekerja).','jkm jaminan kematian meninggal santunan','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 28');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Pensiun','Apa saja manfaat Program Pensiun?','Pensiun sendiri; pensiun warakawuri/janda/duda; pensiun terusan; tunjangan orang tua; tunjangan yatim/piatu; uang duka wafat (3x penerimaan pensiun); tunjangan cacat; nilai tunai iuran pensiun bagi yang berhenti tanpa hak pensiun.','pensiun manfaat janda duda yatim','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 29–32');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Pensiun','Apa kewajiban peserta pensiun?','Autentikasi sebulan sekali lewat aplikasi ASABRI STAR; menyerahkan Surat Pernyataan Tanda Bukti Diri (SPTB) setahun sekali lewat ASABRI Mobile; menyerahkan surat keterangan kuliah untuk anak usia 21–25 tahun paling lambat 1 bulan sebelum ulang tahun anak.','kewajiban pensiunan autentikasi sptb asabri star','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 33');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Pensiun','Apa itu Uang Kekurangan Pensiun (UKP)?','Uang yang dibayarkan kepada penerima pensiun akibat kekurangan pembayaran, pensiun tidak terbit, atau gaji pensiun yang sudah disetorkan ke rekening PT ASABRI. Diajukan ke kantor cabang terdekat.','ukp kekurangan pensiun','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 34');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Klaim','Apa syarat klaim untuk peserta pensiun?','Formulir pengajuan; asli salinan Keputusan Pensiun; fotokopi Keputusan Pengangkatan Pertama/CPNS; asli SKPP dari KPPN/e-SKPP; asli Riwayat Hidup Singkat; surat keterangan kuliah (anak 21–25 tahun); fotokopi e-KTP, KK, surat nikah/KPI/KPS/KARIS/KARSU, NPWP, buku rekening (Mitra Bayar ASABRI); pas foto 4x6 2 lembar. Pindahan dari TASPEN melampirkan voucher Taspen.','syarat klaim pensiun dokumen berkas','Buku Informasi Program Layanan ASABRI 2024 (PDF), hal. 35–36');
INSERT INTO faq (kategori,pertanyaan,jawaban,kata_kunci,sumber) VALUES ('Kontak','Bagaimana menghubungi ASABRI?','Call center 1500043, HP call center 081282371518 / 081282371519, email asabri@asabri.co.id. Pertanyaan juga bisa dikirim lewat form kontak di halaman utama.','kontak call center telepon email hubungi','Halaman utama situs');
